  'useEverywhere.modalAria': 'Pixflow Design\'ı her yerde kullanın',
  'useEverywhere.modalTitle': 'Pixflow Design\'ı her yerde kullanın',
  'useEverywhere.modalSubtitle': 'Pixflow Design\'ı herhangi bir IDE\'ye, Agent\'a veya betiğe bırakın — CLI, HTTP, MCP ve Beceriler. Her şeyi kurmak için "Bir agent için kılavuzu kopyala"yı kullanın ve Claude Code, Codex, Cursor, openclaw veya hermes\'e yapıştırın.',
