  "ui.wpAdminAgentFrameApp.feedback100": "Kullanılabilir yerel CLI çalıştırıcısı yok. Ayarlar → Yürütme bölümünü açıp OpenCode’u veya desteklenen başka bir çalıştırıcıyı bağlayın.",
  "ui.wpAdminAgentFrameApp.feedback101": "Ayarlar → Yürütme bölümünden kullanılabilir bir ajan seçin.",
  "ui.wpAdminAgentFrameApp.feedback102": "Yükleme çalışma alanının bulunabilmesi için {value1} öğesini yeniden ekleyin.",
  "ui.wpAdminAgentFrameApp.feedback103": "Seçili okuma hedefi {value1}, mevcut WordPress yönetici bağlamında yetkilendirilmemiş. Hiçbir değişiklik yapmadım.",
  "ui.wpAdminAgentFrameApp.feedback104": "Açıkça seçilen WordPress yazısı {value1} için güncel yetkilendirme alınamadı. Hiçbir değişiklik yapmadım.",
  "ui.wpAdminAgentFrameApp.feedback105": "Geçerli Gutenberg belgesi tamamen yüklenemedi ({value1}). Hiçbir değişiklik yapmadım.",
  "ui.wpAdminAgentFrameApp.feedback106": "Geçerli Gutenberg belgesi yalnızca bağlı, parçalı bir anlık görüntü olarak kullanılabilir. Gerekli tüm parçalar okunmadan belgenin tamamı için düzenleme hazırlanamaz. Hiçbir değişiklik yapmadım.",
  "ui.wpAdminAgentFrameApp.feedback107": "Geçerli Gutenberg yazısında kaydedilmemiş düzenleyici değişiklikleri var. Pixflow okumadan veya içeriğe duyarlı bir düzenleme hazırlamadan önce kaydedin ya da güncelleyin. Hiçbir değişiklik yapmadım.",
  "ui.wpAdminAgentFrameApp.feedback108": "Tüm Gutenberg bloklarını temizlemek şu anda desteklenmiyor. Pixflow bu isteği boş içerikle değiştirme olarak yorumlamadı ve hiçbir şey değişmedi.",
  "ui.wpAdminAgentFrameApp.feedback109": "Pixflow bu mesajın bekleyen açıklama sorusuna yanıt mı verdiğini yoksa yeni bir istek mi başlattığını belirleyemedi. İnceleme hazırlanmadı ve hiçbir şey değişmedi.",
  "ui.wpAdminAgentFrameApp.feedback110": "Geçerli Gutenberg belgesi parçalara ayrılmış ve tamamen okunmamış, bu yüzden Pixflow tüm belge incelemesi hazırlayamıyor. Hiçbir değişiklik yapmadım.",
  "ui.wpAdminAgentFrameApp.feedback111": "Gutenberg içeriğinin tamamen değiştirilmesi açıkça istenmediğinden Pixflow geçerli belgeyi değiştirmeyi reddetti. Hiçbir şey değişmedi.",
  "ui.wpAdminAgentFrameApp.feedback112": "Pixflow önceki işlemden sonra WordPress nesne yetkisini yenileyemedi. Önceki işlemler geri alınacak.",
  "ui.wpAdminAgentFrameApp.feedback113": "Ön koşul olan yazı geçerli bir WordPress kimliğiyle oluşturulmadı. Önceki işlemler geri alınacak.",
  "ui.wpAdminAgentFrameApp.feedback114": "Pixflow yeni oluşturulan yazı için güncel yetkiyi doğrulayamadı. Önceki işlemler geri alınacak.",
  "ui.wpAdminAgentFrameApp.feedback115": "Yeni oluşturulan yazı, Blok Düzenleyici’de düzenlenebilir bir hedef değil. Önceki işlemler geri alınacak.",
