  "wp.message.26a6374fbf59": "Bir Pixflow eklentisi başlatılamadı. Pixflow eklentilerinizin uyumluluğunu kontrol edip yeniden yükleyin. Diğer özellikler kullanılabilir durumda olabilir.",
  "wp.message.ca7714cffbcc": "Pro’yu etkinleştir",
  "wp.message.197c83a2f752": "Pro eklentisiyle premium araçlarınızı geri getirin. Lisansınız, içeriğiniz ve kayıtlı ayarlarınız korunur. Bricks iki faktörlü kimlik doğrulamasını kullanıyorsanız Pro’yu etkinleştirdikten sonra ayarlardan yeniden açın.",
  "wp.message.2ffdcbc380ea": "Sevdiğiniz sayfa oluşturucuda çalışın. İş akışınıza açıklama notlarını, sesi, tasarım sistemlerini ve görsel oluşturmayı ekleyin.",
  "wp.message.40ed1102964b": "Pro denemesini kontrol et",
  "wp.message.e9cccd3ef5fc": "Kapatma tercihi kaydedilemedi. Lütfen tekrar deneyin.",
  "wp.message.1372089fb797": "Pixflow Pro banner’ını kapat",
  "wp.message.5e3ba715018d": "Pro’yu indir",
  "wp.message.fb2e6d87b44c": "Pixflow Design Pro ile daha fazla olanak",
  "wp.message.9934717ca744": "Bu sayfayı yenileyip tekrar deneyin.",
  "wp.message.7c78f9990490": "7 günlük Pro denemenizi başlatın",
  "wp.message.f89b4dcf2c2e": "Pro’yu 7 gün deneyin",
  "wp.message.69ecce9deb2d": "Bu bildirimi kapatamazsınız.",
  "wp.message.927384e7eed8": "Pixflow planınız Pro içeriyor",
  "wp.message.64585a3a39ef": "[%s] İki faktörlü kimlik doğrulaması sıfırlandı",
  "wp.message.97c3ac935cc2": "[%s] Doğrulama kodunuz",
  "wp.message.b075b6e113fc": "10 dakika",
  "wp.message.8bbe8944007a": "İki faktörlü kimlik doğrulaması",
  "wp.message.c2bf03beb4f6": "İki faktörlü kimlik doğrulaması kurulumu",
  "wp.message.3170543ce47c": "5 dakika",
  "wp.message.0d1fa0dfcc9e": "6 haneli kod",
  "wp.message.8b6693be283d": "Hesap paneli",
