  "wp.message.47d932f4c02a": "Etkin/tamamlanmış numara rengi",
  "wp.message.73dbcf028ec6": "Hesabınızı korumak için ikinci bir doğrulama yöntemi ekleyin.",
  "wp.message.529da8588051": "Girişi tamamlamak için ek doğrulama gerekiyor.",
  "wp.message.6b49000156c3": "Kullanıcı tüm doğrulama yöntemlerini ve kurtarma kodlarını kaybettiğinde yöneticiler bu acil sıfırlamayı kullanabilir.",
  "wp.message.4ea44caf5d6e": "Formdan sonra",
  "wp.message.1be05927766c": "Bir yönetici hesabınızdan iki faktörlü kimlik doğrulamasını kaldırdı. Bu değişikliği beklemiyorsanız şifrenizi sıfırlayın ve hemen site yöneticisiyle iletişime geçin.",
