  "ui.mediaStarter.image1.title": "Editoryal portre",
  "ui.mediaStarter.image1.tag": "Portre",
  "ui.mediaStarter.image1.prompt": "Yirmili yaşlarının sonlarında genç bir kreatif direktörün yakın plan editoryal portresi. Yüksek stüdyo pencerelerinden yumuşak doğal ışık, sıcak nötr palet (krem, boz kahverengi, yumuşak siyah), sığ alan derinliğiyle 85mm f/1.8 çekim, kameraya doğrudan keskin bakış, hafif film grenleri, makyajsız görünüm.",
  "ui.mediaStarter.image2.title": "Ürün ana görseli",
  "ui.mediaStarter.image2.tag": "E-ticaret",
  "ui.mediaStarter.image2.prompt": "Sıcak krem kâğıt fonda tek bir mat seramik kahve kupasının premium ana ürün çekimi. Sol üstten sert kenar ışığı, sağ alta uzanan yumuşak uzun gölge, kupadan yükselen hafif buhar. Kare kırpma, ortalı kompozisyon, üstte başlık için boşluk; kadrajda aksesuar veya el yok.",
  "ui.mediaStarter.image3.title": "Düz illüstrasyon",
  "ui.mediaStarter.image3.tag": "İllüstrasyon",
  "ui.mediaStarter.image3.prompt": "Yağmurlu pencere kenarındaki sıcak bir okuma köşesinin düz vektör illüstrasyonu. Geometrik şekiller, ölçülü beş renkli palet (krem, terakota, koyu camgöbeği, yanık sienna, yumuşak siyah), ince 1.5px çizgi vurguları; gradyan ve doku yok, yalnızca öndeki koltukta yumuşak gölge.",
  "ui.mediaStarter.video1.title": "Ürün tanıtımı",
  "ui.mediaStarter.video1.tag": "Sinematik",
  "ui.mediaStarter.video1.prompt": "Beş saniyelik ürün tanıtımı: temiz krem taş yüzeyde minimalist üst düzey bir cilt bakım şişesi, kamera solundan yumuşak yan ışık, yavaş kamera yaklaşması, kapaktan etikete hafif sığ odak geçişi, ölçülü hareket, yazı katmanı veya insan yok.",
  "ui.mediaStarter.video2.title": "Fener yakın planı",
  "ui.mediaStarter.video2.tag": "Atmosfer",
  "ui.mediaStarter.video2.prompt": "Altın saatte sisli çam ormanında parlayan kâğıt fener tutan genç bir kadının altı saniyelik sinematik yakın planı. Gözlerde sığ alan derinliği, nazik kamera yaklaşması, sıcak ışık huzmesinde süzülen parçacıklar, diyalog yok; yalnızca orman ambiyansı.",
  "ui.mediaStarter.video3.title": "Neon sokakta drift",
  "ui.mediaStarter.video3.tag": "Aksiyon",
  "ui.mediaStarter.video3.prompt": "Neon ışıklı siberpunk bir Hong Kong sokağında gece geçen beş saniyelik sokak yarışı takip çekimi. Dar virajda drift yapan mat siyah spor arabayı izleyen alçak açılı kamera, tekerleklerde hareket bulanıklığı, yaklaşan neon tabelalardan mercek parlamaları, ışıkları yansıtan yağmurlu asfalt; ekranda yazı yok.",
  "ui.mediaStarter.hyperframes1.title": "Büyüteçle açığa çıkarma",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Temiz bir tuvalde tek satır kalın başlık yazısıyla beş saniyelik kompozisyon oluşturun. Yuvarlak bir büyüteç soldan sağa ilerlesin ve altındaki harfleri hafif cam kırılmasıyla büksün. HyperFrames html-in-canvas kullanın: metin DOM'unu yakalayıp üzerine vfx-liquid-glass tarzı bir geçişle mercek gölgelendiricisi uygulayın. Metin saf CSS, cam WebGL katmanı olsun.",
  "ui.mediaStarter.hyperframes2.title": "CRT terminal sahnesi",
  "ui.mediaStarter.hyperframes2.tag": "Nostaljik VFX",
  "ui.mediaStarter.hyperframes2.prompt": "CRT ekran kompozisyonu oluşturun: koyu tuvalde sabit genişlikli terminal metni `npx hyperframes init my-video` yazsın, ardından `claude`, 'Add a CRT effect using HTML-in-canvas' istemiyle çalışsın. html-in-canvas ile canlı DOM üzerine hafif dışbükey eğrilik gölgelendiricisi, tarama çizgileri, az renk sapması ve yumuşak fosfor parıltısı uygulayın. Terminal metni gerçek CSS olarak kalsın; gölgelendirici öncesinde keskin olsun.",
  "ui.mediaStarter.hyperframes3.title": "Glitch parçalanması",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Koyu tuvalde ana başlık ve tek satır alt başlık gösteren altı saniyelik kompozisyon oluşturun. Ardından güçlü dijital glitch oluşsun: RGB kanal ayrımı, yatay kayma şeritleri, kısa kare takılması ve sonunda temiz sıfırlama. Canlı DOM'u html-in-canvas ile yakalayıp üzerine glitch geçişi uygulayın; yazılar gölgelendiricinin altında gerçek CSS olarak kalsın.",
  "ui.mediaStarter.audio1.title": "Marka seslendirmesi",
  "ui.mediaStarter.audio1.tag": "Konuşma",
  "ui.mediaStarter.audio1.prompt": "Ürün lansman videosu için otuz saniyelik sıcak anlatımlı seslendirme: kendinden emin ama sohbet havasında, orta tempo, marka adından sonra kısa duraklama. Metin: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' İngilizce, nötr Kuzey Amerika aksanı.",
  "ui.mediaStarter.audio2.title": "İlk kullanım anlatımı",
  "ui.mediaStarter.audio2.tag": "Konuşma",
  "ui.mediaStarter.audio2.prompt": "Bir mobil uygulamanın ilk açılış ekranı için yirmi saniyelik dostça karşılama anlatımı. Güven veren, gülümseyen ton; metin okunuyormuş gibi olmadan ilgili hissettirecek kadar yavaş. Metin: 'Loop'a hoş geldiniz. Alanınızı hazırlayalım; üç kısa sorudan sonra hazırsınız. Bunların hepsini daha sonra değiştirebilirsiniz.'",
  "ui.mediaStarter.audio3.title": "Öykü bölümü okuması",
  "ui.mediaStarter.audio3.tag": "Konuşma",
  "ui.mediaStarter.audio3.prompt": "Açılış bölümünün kırk beş saniyelik sinematik okuması. Alçak, ölçülü anlatım; cümleler arasında nefes, mikrofona yakın ve biraz samimi ses. Metin: 'Şehir parça parça uyuyor. Ramen tezgâhının üzerinde bir neon tabela titriyor. Caddenin karşısında bir pencere parlıyor; gece yarısının bu tarafında hâlâ yanan tek pencere.'",
  "ui.finalWorkspace.72ed7e2a11": "Yazı tipi ailesi örnekleri",
  "ui.finalWorkspace.6c4afb487e": "Veri türü renk kodlama sistemi",
  "ui.finalWorkspace.c537677ab3": "Arayüz renk paleti",
  "ui.finalWorkspace.ee8acbaf74": "Koyu tema renk paleti",
  "ui.finalWorkspace.f0a7270da4": "Boşluk ölçeği ve kenarlık yarıçapı belirteçleri",
  "ui.finalWorkspace.44c795c914": "Marka logo işaretleri",
  "ui.finalWorkspace.0d0640daac": "Arayüz ve bileşen örüntüleri",
